import { failure } from "./failures.js";
import { RUNTIME_LIMITS } from "./limits.js";
export async function createPrelaunchedBrowserAdapter(options) {
    const { server, cdpEndpoint } = options;
    const attachTimeoutMs = options.attachTimeoutMs ?? RUNTIME_LIMITS.browserAttachTimeoutMs;
    let playwright;
    try {
        playwright = server.createPlaywright({
            sdkLanguage: "javascript",
            isServer: true,
        });
    }
    catch {
        return {
            kind: "rejected",
            failure: failure("launch_failed", "Playwright server failed to start"),
        };
    }
    // Chrome may still be starting when this server spawns, so attach on first
    // use and retry on the next connection after a failure.
    let attaching;
    const attachedBrowser = async (replaceDisconnected = true) => {
        attaching ??= playwright.chromium.connectOverCDP(server.nullProgress, {
            endpointURL: cdpEndpoint,
            noDefaults: true,
        });
        const attempt = attaching;
        let browser;
        try {
            browser = await withTimeout(attempt, attachTimeoutMs);
        }
        catch (error) {
            if (attaching === attempt)
                attaching = undefined;
            throw error;
        }
        if (!replaceDisconnected || !isDisconnected(browser))
            return browser;
        if (attaching === attempt)
            attaching = undefined;
        return await attachedBrowser(false);
    };
    return {
        kind: "admitted",
        value: {
            kind: "prelaunched-browser",
            page: { kind: "existing-visible-page" },
            async connect() {
                try {
                    const browser = await attachedBrowser();
                    return {
                        kind: "admitted",
                        value: createDispatcherChannel({ server, playwright, browser }),
                    };
                }
                catch (error) {
                    return {
                        kind: "rejected",
                        failure: failure("launch_failed", browserAttachFailureMessage(error, cdpEndpoint)),
                    };
                }
            },
            async close() { },
        },
    };
}
function withTimeout(promise, timeoutMs) {
    return new Promise((resolve, reject) => {
        const timer = setTimeout(() => reject(new Error(`Timeout ${timeoutMs}ms exceeded while attaching`)), timeoutMs);
        promise.then((value) => {
            clearTimeout(timer);
            resolve(value);
        }, (error) => {
            clearTimeout(timer);
            reject(error);
        });
    });
}
function isDisconnected(browser) {
    return ("isConnected" in browser &&
        typeof browser.isConnected === "function" &&
        browser.isConnected() === false);
}
function browserAttachFailureMessage(error, cdpEndpoint) {
    const detail = typeof error === "object" && error !== null && "message" in error
        ? String(error.message).split("\n", 1)[0]
        : "";
    const message = `Chrome is not reachable at ${cdpEndpoint}${detail === "" ? "" : `: ${detail}`}`;
    return message.length <= 200 ? message : `${message.slice(0, 199)}…`;
}
function createDispatcherChannel(options) {
    const { server, playwright, browser } = options;
    const connection = new server.DispatcherConnection();
    const root = new server.RootDispatcher(connection, async (scope) => {
        return new server.PlaywrightDispatcher(scope, playwright, {
            preLaunchedBrowser: browser,
            denyLaunch: true,
            sharedBrowser: true,
        });
    });
    let messageListener = () => undefined;
    let closeListener = () => undefined;
    let closed = false;
    connection.onmessage = (message) => messageListener(JSON.stringify(message));
    const close = () => {
        if (closed) {
            return;
        }
        closed = true;
        void root.stopPendingOperations(new Error("Playwright proxy disconnected")).finally(() => {
            root._dispose();
            closeListener();
        });
    };
    return {
        send(message) {
            if (closed) {
                return;
            }
            try {
                void connection.dispatch(JSON.parse(message)).catch(close);
            }
            catch {
                close();
            }
        },
        close,
        onMessage(listener) {
            messageListener = listener;
        },
        onClose(listener) {
            closeListener = listener;
        },
    };
}
